package org.apache.commons.csv;

import java.io.*;
import java.io.Closeable;
import java.io.Flushable;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.sql.ResultSet;
import java.sql.ResultSetMetaData;
import java.sql.SQLException;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CSVPrinter_printRecords_TriageGen2Test {

    @Test
    public void testPrintRecords_WithMultipleRows() throws SQLException, IOException {
        // Setup
        StringWriter out = new StringWriter();
        CSVPrinter printer = new CSVPrinter(out, CSVFormat.DEFAULT);

        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(2);

        // Row 1
        when(resultSet.next()).thenReturn(true, true, false);
        when(resultSet.getString(1)).thenReturn("A", "B");
        when(resultSet.getString(2)).thenReturn("C", "D");

        // Execute
        printer.printRecords(resultSet);
        printer.close();

        // Verify: CSVFormat.DEFAULT uses comma as delimiter and CRLF/LF depending on OS. 
        // For standard unit tests, we assume default CSV behavior.
        // Row 1: A,C
        // Row 2: B,D
        String expected = "A,C" + System.lineSeparator() + "B,D" + System.lineSeparator();
        assertEquals(expected, out.toString());
    }

    @Test
    public void testPrintRecords_WithEmptyResultSet() throws SQLException, IOException {
        // Setup
        StringWriter out = new StringWriter();
        CSVPrinter printer = new CSVPrinter(out, CSVFormat.DEFAULT);

        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(3);
        when(resultSet.next()).thenReturn(false);

        // Execute
        printer.printRecords(resultSet);
        printer.close();

        // Verify
        assertEquals("", out.toString());
    }

    @Test
    public void testPrintRecords_WithSingleColumn() throws SQLException, IOException {
        // Setup
        StringWriter out = new StringWriter();
        CSVPrinter printer = new CSVPrinter(out, CSVFormat.DEFAULT);

        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(1);

        when(resultSet.next()).thenReturn(true, false);
        when(resultSet.getString(1)).thenReturn("Value");

        // Execute
        printer.printRecords(resultSet);
        printer.close();

        // Verify
        String expected = "Value" + System.lineSeparator();
        assertEquals(expected, out.toString());
    }

    @Test(expected = SQLException.class)
    public void testPrintRecords_ThrowsSQLException() throws SQLException, IOException {
        // Setup
        StringWriter out = new StringWriter();
        CSVPrinter printer = new CSVPrinter(out, CSVFormat.DEFAULT);

        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(1);
        when(resultSet.next()).thenThrow(new SQLException("Database error"));

        // Execute
        printer.printRecords(resultSet);
    }

    @Test(expected = IOException.class)
    public void testPrintRecords_ThrowsIOException() throws SQLException, IOException {
        // Setup a custom Appendable that throws IOException
        Appendable errorOut = new Appendable() {
            @Override
            public Appendable append(CharSequence csq) throws IOException { throw new IOException("Write error"); }
            @Override
            public Appendable append(CharSequence csq, int start, int end) throws IOException { throw new IOException("Write error"); }
            @Override
            public Appendable append(char c) throws IOException { throw new IOException("Write error"); }
        };

        CSVPrinter printer = new CSVPrinter(errorOut, CSVFormat.DEFAULT);

        ResultSet resultSet = mock(ResultSet.class);
        ResultSetMetaData metaData = mock(ResultSetMetaData.class);

        when(resultSet.getMetaData()).thenReturn(metaData);
        when(metaData.getColumnCount()).thenReturn(1);
        when(resultSet.next()).thenReturn(true);
        when(resultSet.getString(1)).thenReturn("Data");

        // Execute
        printer.printRecords(resultSet);
    }
}
